"""Action arbitration utilities for policy control and live teleoperation.

The VLA client can receive two independent streams of actions:

* policy actions generated by the inference pipeline;
* teleoperation actions coming from a human control bridge.

This module keeps the selection logic small and explicit.  Teleoperation has
priority while it is fresh, policy is used as the normal fallback, and the last
selected action is held when neither input source has produced a recent value.
"""

from dataclasses import dataclass
from enum import Enum
import threading
from typing import Optional, Union

import numpy as np


class ActionSource(str, Enum):
    """Known producers, plus the synthetic HOLD fallback selected by the arbiter."""

    POLICY = "policy"
    TELEOP = "teleop"
    HOLD = "hold"


@dataclass(frozen=True)
class SelectedAction:
    """A selected action and the metadata needed by transition filtering.

    ``previous_source`` and ``source_changed`` deliberately live on the selected
    output instead of inside the filter.  This keeps the arbiter responsible for
    source transitions and lets the filter focus only on shaping the numeric
    action vector.

    ``mask`` marks which entries of ``action`` are real control data from the
    producer. ``None`` means the producer did not provide one.
    """

    source: ActionSource
    action: np.ndarray
    previous_source: Optional[ActionSource] = None
    source_changed: bool = False
    mask: Optional[np.ndarray] = None


@dataclass(frozen=True)
class _ActionRecord:
    """Latest action submitted by one real input source."""

    source: ActionSource
    action: np.ndarray
    timestamp: float
    mask: Optional[np.ndarray] = None


class ActionArbiter:
    """Select the best action source for the current control tick.

    The policy is intentionally simple and deterministic:

    1. use TELEOP if a fresh human action exists;
    2. otherwise use POLICY if a fresh policy action exists;
    3. otherwise HOLD the last selected action.

    The class is thread-safe because teleop callbacks, inference, and control
    can run on different threads.
    """

    def __init__(self, action_timeout_s: float = 0.5, policy_timeout_s: float = 0.5):
        self.action_timeout_s = float(action_timeout_s)
        self.policy_timeout_s = float(policy_timeout_s)
        self._lock = threading.Lock()
        self._latest: dict[ActionSource, _ActionRecord] = {}
        self._last_selected: Optional[SelectedAction] = None

    def submit(self, source: Union[ActionSource, str], action, timestamp: float, mask=None) -> None:
        """Store the newest action for one real producer.

        ``HOLD`` is rejected here because it is not an external producer; it is a
        fallback state synthesized by :meth:`select`. ``mask`` optionally marks
        which entries of ``action`` are real control data.
        """

        source = ActionSource(source)
        if source == ActionSource.HOLD:
            raise ValueError("HOLD is a selected fallback, not an input source")
        arr = np.asarray(action, dtype=float).copy()
        mask_arr = None
        if mask is not None:
            mask_arr = np.asarray(mask, dtype=bool).reshape(-1).copy()
            if mask_arr.shape[0] != arr.reshape(-1).shape[0]:
                raise ValueError(
                    f"Action mask width {mask_arr.shape[0]} does not match action width {arr.reshape(-1).shape[0]}"
                )
        record = _ActionRecord(source=source, action=arr, timestamp=float(timestamp), mask=mask_arr)
        with self._lock:
            self._latest[source] = record

    def select(self, now: Optional[float] = None) -> Optional[SelectedAction]:
        """Return the action that should be executed at ``now``.

        ``None`` is returned only before any source has ever produced an action.
        After the first successful selection, stale periods return a HOLD action
        so the robot keeps a stable command instead of receiving gaps.
        """

        if now is None:
            import time
            now = time.perf_counter()
        now = float(now)
        with self._lock:
            for source in (ActionSource.TELEOP, ActionSource.POLICY):
                record = self._latest.get(source)
                if record is not None and self._is_fresh(record, now):
                    previous_source = self._last_selected.source if self._last_selected is not None else None
                    source_changed = previous_source is not None and previous_source != source
                    selected = SelectedAction(
                        source=source,
                        action=record.action.copy(),
                        previous_source=previous_source,
                        source_changed=source_changed,
                        mask=None if record.mask is None else record.mask.copy(),
                    )
                    self._last_selected = selected
                    return selected
            if self._last_selected is None:
                return None
            previous_source = self._last_selected.source
            source_changed = previous_source != ActionSource.HOLD
            selected = SelectedAction(
                source=ActionSource.HOLD,
                action=self._last_selected.action.copy(),
                previous_source=previous_source,
                source_changed=source_changed,
            )
            self._last_selected = selected
            return selected

    def clear(self) -> None:
        """Drop all source records and reset HOLD history."""

        with self._lock:
            self._latest.clear()
            self._last_selected = None

    def clear_source(self, source: Union[ActionSource, str]) -> None:
        """Drop the latest record for one producer without clearing HOLD history."""

        source = ActionSource(source)
        if source == ActionSource.HOLD:
            return
        with self._lock:
            self._latest.pop(source, None)

    def last_submitted_at(self, source: Union[ActionSource, str]) -> Optional[float]:
        """Return the newest submission timestamp for one source."""

        source = ActionSource(source)
        with self._lock:
            record = self._latest.get(source)
            return None if record is None else record.timestamp

    def latest_action(self, source: Union[ActionSource, str]) -> Optional[np.ndarray]:
        """Return a copy of the newest action for one source."""

        source = ActionSource(source)
        with self._lock:
            record = self._latest.get(source)
            return None if record is None else record.action.copy()

    def latest_mask(self, source: Union[ActionSource, str]) -> Optional[np.ndarray]:
        """Return a copy of the newest action mask for one source, if any."""

        source = ActionSource(source)
        with self._lock:
            record = self._latest.get(source)
            return None if record is None or record.mask is None else record.mask.copy()

    def _is_fresh(self, record: _ActionRecord, now: float) -> bool:
        """Check freshness with source-specific timeout windows."""

        if record.source == ActionSource.POLICY:
            return now - record.timestamp <= self.policy_timeout_s
        return now - record.timestamp <= self.action_timeout_s


class ActionTransitionFilter:
    """Smooth numeric action jumps when the selected source changes.

    Switching from policy to teleop, teleop to policy, or any source to HOLD can
    otherwise create discontinuities.  The filter performs a short linear blend
    and can optionally clamp the maximum per-tick delta.
    """

    def __init__(self, transition_steps: int = 0, max_delta_per_step: Optional[float] = None):
        self.transition_steps = max(0, int(transition_steps))
        self.max_delta_per_step = None if max_delta_per_step is None else float(max_delta_per_step)
        self._last_output: Optional[np.ndarray] = None
        self._transition_start: Optional[np.ndarray] = None
        self._transition_target: Optional[np.ndarray] = None
        self._transition_remaining = 0

    def filter(self, selected: SelectedAction) -> np.ndarray:
        """Return a smoothed version of the selected target action."""

        target = np.asarray(selected.action, dtype=float).copy()
        if self._last_output is None:
            self._last_output = target
            return target.copy()

        if selected.source_changed and self.transition_steps > 0:
            self._transition_start = self._last_output.copy()
            self._transition_target = target.copy()
            self._transition_remaining = self.transition_steps

        if self._transition_remaining > 0 and self._transition_start is not None and self._transition_target is not None:
            completed = self.transition_steps - self._transition_remaining + 1
            alpha = completed / float(self.transition_steps + 1)
            output = (1.0 - alpha) * self._transition_start + alpha * self._transition_target
            self._transition_remaining -= 1
        else:
            output = target

        output = self._apply_delta_limit(output)
        self._last_output = output.copy()
        return output

    def reset(self, last_output=None) -> None:
        """Clear smoothing state, optionally seeding the next output."""

        self._last_output = None if last_output is None else np.asarray(last_output, dtype=float).copy()
        self._transition_start = None
        self._transition_target = None
        self._transition_remaining = 0

    def _apply_delta_limit(self, output: np.ndarray) -> np.ndarray:
        """Apply an optional absolute delta bound around the previous output."""

        if self.max_delta_per_step is None or self.max_delta_per_step <= 0:
            return output
        lower = self._last_output - self.max_delta_per_step
        upper = self._last_output + self.max_delta_per_step
        return np.clip(output, lower, upper)
